<?php $this->layout('layouts/erp');$types=['receivable'=>'Receber','payable'=>'Pagar'];$statuses=['open'=>'Aberto','partial'=>'Parcial','paid'=>'Pago','overdue'=>'Vencido','cancelled'=>'Cancelado']; ?>
<style>.finance-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0}.finance-summary article{padding:16px;border:1px solid #e5e7eb;border-radius:10px;background:#fff}.finance-summary small,.finance-summary strong{display:block}.finance-summary strong{margin-top:8px;font-size:1.25rem}.page_main>form,.page_main>section>form{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0}.page_main input,.page_main select,.page_main button{padding:10px 12px;border:1px solid #d7dce4;border-radius:7px;background:#fff}.page_main button{border-color:#c5a131;background:#c5a131;color:#fff}.page_main td form{display:flex;gap:6px;margin:4px 0}.page_main td small{display:block;color:#777}@media(max-width:800px){.finance-summary{grid-template-columns:repeat(2,1fr)}.page_main{overflow-x:auto}}</style>
<?php if(!$condo->select):?><?php $this->insert('/pages/welcome-condo');?><?php else:?>
<div class="container"><?php $this->insert('components/finance/sidebar');?><main class="page_main">
<header><h1>Lançamentos financeiros</h1><p>Contas a receber, contas a pagar e pagamentos do condomínio selecionado.</p></header>
<section class="finance-summary"><article><small>A receber</small><strong>R$ <?= number_format((float)$totals['receivable'],2,',','.') ?></strong></article><article><small>Recebido</small><strong>R$ <?= number_format((float)$totals['received'],2,',','.') ?></strong></article><article><small>A pagar</small><strong>R$ <?= number_format((float)$totals['payable'],2,',','.') ?></strong></article><article><small>Pago</small><strong>R$ <?= number_format((float)$totals['paid'],2,',','.') ?></strong></article></section>
<form class="ajax_off" method="get" action="<?= url('/erp/finance/entries') ?>"><input name="q" value="<?= htmlspecialchars((string)($filters['q']??'')) ?>" placeholder="Descrição ou documento"><select name="type"><option value="">Receber e pagar</option><?php foreach($types as $key=>$label):?><option value="<?= $key ?>" <?= ($filters['type']??'')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select><select name="status"><option value="">Todos os status</option><?php foreach($statuses as $key=>$label):?><option value="<?= $key ?>" <?= ($filters['status']??'')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select><button type="submit">Filtrar</button></form>
<section><h2><?= $edit?'Editar lançamento':'Novo lançamento' ?></h2><form method="post" action="<?= url('/erp/finance/entries') ?>"><?= csrf_input() ?><input type="hidden" name="action" value="<?= $edit?'update':'create' ?>"><?php if($edit):?><input type="hidden" name="entry_id" value="<?= (int)$edit->id ?>"><?php endif;?><select name="type" required><?php foreach($types as $key=>$label):?><option value="<?= $key ?>" <?= ($edit->type??($filters['type']??''))===$key?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select><input name="description" required minlength="3" maxlength="220" value="<?= htmlspecialchars((string)($edit->description??'')) ?>" placeholder="Descrição"><input name="document_number" maxlength="80" value="<?= htmlspecialchars((string)($edit->document_number??'')) ?>" placeholder="Documento"><label>Competência<input type="date" name="competency" required value="<?= htmlspecialchars((string)($edit->competency??date('Y-m-01'))) ?>"></label><label>Vencimento<input type="date" name="due_at" required value="<?= htmlspecialchars((string)($edit->due_at??date('Y-m-d'))) ?>"></label><label>Valor<input name="amount" inputmode="decimal" required value="<?= htmlspecialchars((string)($edit->amount??'')) ?>" placeholder="0,00"></label><button type="submit">Salvar lançamento</button><?php if($edit):?><a href="<?= url('/erp/finance/entries') ?>">Cancelar edição</a><?php endif;?></form></section>
<table><thead><tr><th>Vencimento</th><th>Descrição</th><th>Tipo</th><th>Valor</th><th>Pago</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php if(!$items):?><tr><td colspan="7">Nenhum lançamento encontrado.</td></tr><?php endif;?><?php foreach($items as $item):?><tr><td><?= date_fmt($item->due_at,'d/m/Y') ?></td><td><strong><?= htmlspecialchars($item->description) ?></strong><small><?= htmlspecialchars((string)$item->document_number) ?></small></td><td><?= $types[$item->type]??$item->type ?></td><td>R$ <?= number_format((float)$item->amount,2,',','.') ?></td><td>R$ <?= number_format((float)$item->paid_amount,2,',','.') ?></td><td><?= $statuses[$item->status]??$item->status ?></td><td><?php if((float)$item->paid_amount===0.0&&!in_array($item->status,['paid','cancelled'],true)):?><a href="<?= url('/erp/finance/entries?edit='.$item->id) ?>">Editar</a><form method="post" action="<?= url('/erp/finance/entries') ?>"><?= csrf_input() ?><input type="hidden" name="action" value="cancel"><input type="hidden" name="entry_id" value="<?= (int)$item->id ?>"><button type="submit">Cancelar</button></form><?php endif;?><?php if(!in_array($item->status,['paid','cancelled'],true)):?><form method="post" action="<?= url('/erp/finance/entries') ?>"><?= csrf_input() ?><input type="hidden" name="action" value="pay"><input type="hidden" name="entry_id" value="<?= (int)$item->id ?>"><input name="payment_amount" required inputmode="decimal" placeholder="Valor pago"><input type="date" name="paid_at" value="<?= date('Y-m-d') ?>" required><button type="submit">Registrar pagamento</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table>
</main></div><?php endif;?>
